import React, { useState } from 'react';
import { Container, Row, Col, InputGroup, FormControl, Button } from 'react-bootstrap';
import { XCircle, Search } from 'react-bootstrap-icons';

const SearchPageHeader = () => {
  const [searchText, setSearchText] = useState('https://freenews4u.com/newsarticle');

  return (
    <Container fluid className="d-flex align-items-center justify-content-center" style={{ padding: '20px' }}>
      <Row className="w-100">
        <Col xs={2} className="d-flex align-items-center">
          <a href="https://freenews4u.com" className="text-primary">Searchify</a>
        </Col>
        <Col xs={8}>
          <InputGroup style={{ width: '100%' }}>
            <FormControl
              type="text"
              value={searchText}
              onChange={(e) => setSearchText(e.target.value)}
              style={{ borderRadius: '25px 0 0 25px', border: 'none', backgroundColor: '#e1e1e1' }}
            />
            <InputGroup.Append>
              <Button variant="link" style={{ borderRadius: '0 25px 25px 0', border: 'none', backgroundColor: '#e1e1e1' }}>
                <XCircle size={20} />
              </Button>
              <Button variant="link" style={{ borderRadius: '0 25px 25px 0', border: 'none', backgroundColor: '#e1e1e1' }}>
                <Search size={20} />
              </Button>
            </InputGroup.Append>
          </InputGroup>
        </Col>
        <Col xs={2}></Col>
      </Row>
    </Container>
  );
};

export default SearchPageHeader;
